from typing import List, Literal
from pydantic import BaseModel, Field


CabinClass = Literal["business", "economy", "basic_economy"]


class FlightInfo(BaseModel):
    flight_number: str = Field(description="Flight number copied from get_reservation_details (unchanged flights) or from a search result (new flights). Never invent one.")
    date: str = Field(
        description="The date for the flight in the format 'YYYY-MM-DD', such as '2024-05-01'."
    )


def update_reservation_flights(reservation_id: str, cabin: CabinClass, flights: List[FlightInfo | dict], payment_id: str):
    """
    Update the flight information of a reservation.

    Steps:
    1. BEFORE asking the user to confirm, call calculate_flight_change_cost with the same
       reservation_id, cabin and flights, and tell the user its exact "user_will_pay" amount.
       The cabin applies to ALL flights of the reservation (one cabin per reservation), so a cabin
       change re-prices the return flights too. Never quote a price you computed yourself.
    2. Get an explicit "yes" from the user, then call this tool.

    CABIN-ONLY change (upgrade/downgrade, e.g. basic_economy -> business): pass the reservation's CURRENT
    flights exactly as get_reservation_details lists them (same flight_number and date, same order).
    Example: reservation flights are [<flight A> on <date A>, <flight B> on <date B>] and the user wants business:
        update_reservation_flights(reservation_id="<id>", cabin="business",
            flights=[{"flight_number": "<flight A>", "date": "<date A>"}, {"flight_number": "<flight B>", "date": "<date B>"}],
            payment_id="<credit card or gift card id from the profile>")

    BASIC ECONOMY: a basic_economy reservation CAN be upgraded to economy or business (cabin-only change,
    same flights). Do not tell the user it cannot be upgraded. Only its flights cannot be changed.
    The tool refuses a flight change on a basic_economy reservation. If the user wants other flights,
    tell them; they may cancel (only if cancel_reservation allows it) and book a new reservation.

    This tool returns "Error: ..." without changing anything if payment_id is not a credit card or gift
    card id from the user's profile, or if the flights do not form a continuous route (each flight
    must depart from the airport where the previous flight arrived).

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        cabin: The cabin class of the WHOLE reservation after the change: 'basic_economy', 'economy' or 'business'.
        flights: An array of objects containing details about each piece of flight in the ENTIRE new reservation. Even if the a flight segment is not changed, it should still be included in the array, with its original flight_number and date. Keep the order: outbound flights first, then return flights.
        payment_id: The exact payment id from the user's profile (get_user_details "payment_methods"), for example '<credit_card_id>' or '<gift_card_id>'. Certificates cannot be used here. Never build an id from a card's last four digits.

    Returns:
        The updated reservation.

    Raises:
        ValueError: If the reservation is not found.
        ValueError: If the user is not found.
        ValueError: If the payment method is not found.
        ValueError: If the certificate cannot be used to update reservation.
        ValueError: If the gift card balance is not enough.
    """
    def _d(x):
        if hasattr(x, "model_dump"):
            return x.model_dump()
        return dict(x)

    flights = [_d(f) for f in flights]
    res = env_get_reservation_details(reservation_id=reservation_id)
    if isinstance(res, dict):
        user = env_get_user_details(user_id=res.get("user_id"))
        if isinstance(user, dict):
            methods = user.get("payment_methods") or {}
            usable = [m for m in methods.values() if m.get("source") in ("credit_card", "gift_card")]

            def _describe(m):
                s = m.get("id", "") + " (" + str(m.get("source"))
                if m.get("brand"):
                    s += ", " + str(m.get("brand"))
                if m.get("last_four"):
                    s += " ending in " + str(m.get("last_four"))
                if m.get("amount") is not None:
                    s += ", balance $" + str(m.get("amount"))
                return s + ")"

            if payment_id not in methods:
                return ("Error: payment_id '" + str(payment_id) + "' is not in this user's profile. Nothing was changed. "
                        "Usable ids for a flight change: " + "; ".join(_describe(m) for m in usable) +
                        ". If you are not sure which one the user means, ask the user.")
            if methods[payment_id].get("source") == "certificate":
                return ("Error: a certificate cannot pay for a flight change. Nothing was changed. "
                        "Usable ids: " + "; ".join(_describe(m) for m in usable) + ".")

        cur = res.get("flights") or []
        cur_list = ", ".join(f["flight_number"] + " " + f["origin"] + "->" + f["destination"] + " " + f["date"] for f in cur)
        cur_keys = «redacted» f["date"]) for f in cur]
        new_keys = «redacted» f.get("date")) for f in flights]

        # basic economy: flights cannot be modified (only the cabin)
        if res.get("cabin") == "basic_economy" and new_keys != cur_keys:
            «redacted» ("Error: reservation " + reservation_id + " is basic economy, and basic economy flights cannot be "
                    "changed. Nothing was changed. Only the cabin can be changed, keeping exactly the current flights: " +
                    cur_list + ". For a cabin-only change call again with exactly these flights. If the user wants "
                    "different flights, tell them basic economy flights cannot be modified; they could cancel "
                    "(only if cancel_reservation allows it) and book a new reservation.")

        # every NEW flight must exist on this reservation's route on that date
        routes = {}
        for f in cur:
            routes[f["flight_number"]] = (f["origin"], f["destination"])
        o0, d0 = res.get("origin"), res.get("destination")
        cache = {}

        def _search(kind, a, b, date):
            key = «redacted» a, b, date)
            if key not in cache:
                if kind == "direct":
                    cache[key] = env_search_direct_flight(origin=a, destination=b, date=date)
                else:
                    cache[key] = env_search_onestop_flight(origin=a, destination=b, date=date)
            return cache[key] if isinstance(cache[key], list) else []

        def _prev(date):
            try:
                import datetime as _dt
                return (_dt.date.fromisoformat(date) - _dt.timedelta(days=1)).isoformat()
            except Exception:
                return None

        def _find(fn, date):
            for (a, b) in ((o0, d0), (d0, o0)):
                for x in _search("direct", a, b, date):
                    if x.get("flight_number") == fn:
                        return (x.get("origin"), x.get("destination"))
                for dd in (date, _prev(date)):
                    if not dd:
                        continue
                    for pair in _search("onestop", a, b, dd):
                        for x in pair:
                            if x.get("flight_number") == fn and x.get("date") in (None, date):
                                return (x.get("origin"), x.get("destination"))
            return None

        for f in flights:
            k = (f.get("flight_number"), f.get("date"))
            if k in cur_keys:
                «redacted»
            r = _find(k[0], k[1])
            if r is None:
                return ("Error: flight " + str(k[0]) + " on " + str(k[1]) + " is not an available flight between " +
                        str(o0) + " and " + str(d0) + " on that date. Nothing was changed. Use a flight_number and date "
                        "exactly as returned by search_direct_flight / search_onestop_flight. Current flights of this "
                        "reservation: " + cur_list + " (for a cabin-only change, pass exactly these).")
            routes[k[0]] = r
        if flights:
            first = routes.get(flights[0].get("flight_number"))
            if first and first[0] != o0:
                return ("Error: the new itinerary must start at the reservation origin " + str(o0) + " but the first flight " +
                        flights[0]["flight_number"] + " departs from " + first[0] + ". Nothing was changed. The origin, "
                        "destination and trip type cannot change. Current flights: " + cur_list + ".")
        for i in range(len(flights) - 1):
            a = routes.get(flights[i].get("flight_number"))
            b = routes.get(flights[i + 1].get("flight_number"))
            if a and b and a[1] != b[0]:
                return ("Error: the flights do not form a continuous route: " + flights[i]["flight_number"] + " arrives at " +
                        a[1] + " but the next flight " + flights[i + 1]["flight_number"] + " departs from " + b[0] +
                        ". Nothing was changed. Include EVERY flight of the new itinerary in order; unchanged flights keep "
                        "their original flight_number and date. Current flights: " + cur_list + ".")

    return env_update_reservation_flights(reservation_id=reservation_id, cabin=cabin, flights=flights, payment_id=payment_id)
